package edu.pe.cibertec.saibm.libro.infrastructure.out.persistence;
import java.util.*; import org.springframework.data.domain.PageRequest; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import edu.pe.cibertec.saibm.libro.application.port.out.BookRepositoryPort; import edu.pe.cibertec.saibm.libro.domain.model.Book;
@Component @Transactional public class BookPersistenceAdapter implements BookRepositoryPort { private final SpringDataBookRepository repo; public BookPersistenceAdapter(SpringDataBookRepository r){repo=r;} @Transactional(readOnly=true) public Optional<Book> find(UUID id){return repo.findById(id).map(BookJpaEntity::domain);} public Book save(Book b){return repo.save(BookJpaEntity.from(b)).domain();} @Transactional(readOnly=true) public Page search(String q,int page,int size){var p=repo.active(q,PageRequest.of(page,size));return new Page(p.getContent().stream().map(BookJpaEntity::domain).toList(),page,size,p.getTotalElements());} }
